-- CONTENT_MD prototype, round 2 (2026-10-15): do the links of 17 pages of other entity types
-- (series, episode, season, award, place, genre, company, collection, list, source work) point to
-- entities we hold, and how far a local title join goes. Same measures as
-- check-content-md-prototype-links.sql (round 1). Read-only, temporary tables only.
CREATE TEMPORARY TABLE TMP_PROTO_LINK (PAGE varchar(100), LANG varchar(10), TARGET varchar(300), QID varchar(20), KEY (LANG, TARGET), KEY (QID)) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
