-- Title hits in one scan of PAGE_LANG (WIKIPEDIA_PAGE_TITLE has no index).
CREATE TEMPORARY TABLE TMP_PROTO_TITLE_HIT AS
SELECT STRAIGHT_JOIN DISTINCT t.LANG, t.TARGET, p.ID_WIKIDATA
FROM T_WC_WIKIPEDIA_PAGE_LANG p
INNER JOIN TMP_PROTO_LINK t ON t.LANG = p.LANG AND t.TARGET = p.WIKIPEDIA_PAGE_TITLE;

CREATE TEMPORARY TABLE TMP_PROTO_QID_HELD (PRIMARY KEY (QID)) AS
SELECT DISTINCT l.QID FROM TMP_PROTO_LINK l
WHERE l.QID <> '' AND EXISTS (SELECT 1 FROM T_WC_WIKIPEDIA_PAGE_LANG p WHERE p.ID_WIKIDATA = l.QID);

SELECT l.PAGE,
  COUNT(*) AS LINKS,
  COUNT(DISTINCT NULLIF(l.QID, '')) AS DISTINCT_QIDS,
  COUNT(DISTINCT h2.QID) AS QIDS_WE_CRAWL,
  COUNT(h.TARGET) AS LINKS_RESOLVED_BY_LOCAL_TITLE,
  SUM(h.ID_WIKIDATA IS NOT NULL AND h.ID_WIKIDATA <> l.QID) AS LOCAL_TITLE_WRONG_QID
FROM TMP_PROTO_LINK l
LEFT JOIN TMP_PROTO_TITLE_HIT h ON h.LANG = l.LANG AND h.TARGET = l.TARGET
LEFT JOIN TMP_PROTO_QID_HELD h2 ON h2.QID = l.QID
GROUP BY l.PAGE WITH ROLLUP;
